contract InvMutTest {
    C c;
    uint256 public seenCount;
    address public seenFrom;
    address public seenTo;
    uint256 public seenValue;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address from, address caddress, address[] memory tos, uint v, uint decimals) public payable {
        require(tos.length == 1);
        require(decimals <= 18);

        bool reverted;
        bool returned;
        try c.transfer(from, caddress, tos, v, decimals) returns (bool r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || (returned && seenValue == v * 10 ** decimals));
    }

    function onTransferFrom(address from, address to, uint256 value) external {
        seenCount++;
        seenFrom = from;
        seenTo = to;
        seenValue = value;
    }
}

