contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint v, uint decimals) public payable {
        require(tos.length > 0);

        uint _value = v * 10 ** decimals;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));

        bool externalWouldSucceed = true;
        for (uint i = 0; i < tos.length; i++) {
            (bool s, ) = caddress.call(abi.encodeWithSelector(id, from, tos[i], _value));
            if (!s) {
                externalWouldSucceed = false;
                break;
            }
        }

        bool reverted;
        bool returnedTrue;
        try c.transfer(from, caddress, tos, v, decimals) returns (bool ok) {
            reverted = false;
            returnedTrue = ok;
        } catch {
            reverted = true;
        }

        assert(reverted || (returnedTrue && externalWouldSucceed));
    }

    receive() external payable {}
}

